context_info = ()
for d in context:
    r = llm_query("You will be given one document. The 'machine' in the user's question refers to an elevator (US) / lift (UK). We are looking for an article (likely from the 2010s) about incidents/accidents surrounding elevators/lifts that includes a story where someone's sibling was injured by an elevator on Thanksgiving and suffered a catastrophic injury.\n\nInstructions:\n- Read the document below.\n- If the document contains such a story, extract the following:\n  - Name: the full name of the person whose sibling was injured (not the injured sibling’s name).\n  - Year: the publication year if present or inferable from the document; otherwise write \"unknown\".\n  - Source: the article/site title or identifier if present; otherwise write \"unknown\".\n  - Quotes: brief quotes that explicitly mention Thanksgiving and catastrophic injury (or equivalent phrasing) that supports the extraction.\n- If the document does NOT contain such a story, output nothing at all.\n\nFormat the output exactly as follows if and only if a match is found:\nName: <full name>\nYear: <year or unknown>\nSource: <source or unknown>\nQuotes:\n\"<quote 1>\"\n\"<quote 2>\" (include if helpful)\n\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT")
    context_info = context_info + (r,)

combined = "\n---\n".join(context_info)

final_answer = llm_query("We are answering this user question:\n\"According to an article from the 2010s about incidents surrounding elevators/lifts, what is the name of the person whose sibling got injured by this machine on Thanksgiving and sustained a catastrophic injury?\"\n\nBelow are candidate extractions from the context documents (some may be empty if no match was found):\n\n" + combined + "\n\nTask:\n- From the above, pick the single best matching extraction where the story clearly states someone's sibling was injured by an elevator (lift) on Thanksgiving and suffered a catastrophic injury.\n- Prefer entries that come from an article in the 2010s if Year is provided; otherwise, rely on the strongest matching quotes.\n- Output ONLY the person's full name (the person whose sibling was injured), with no extra words, punctuation, or explanation.")

return_result(final_answer.strip())